const L = wall_length, H = height, S = brick_length, bh = brick_height, m = mortar, d = (S - m) / 2, hd = (S - m) / 2, s = seed, j = jitter;
const rows = Math.ceil((H + m) / (bh + m));
for (let r = 0; r < rows; r++) {
  const y0 = r * (bh + m), y1 = Math.min(H, y0 + bh);
  if (y1 - y0 < 0.004) break;
  const odd = r % 2 === 1;
  let units, off;
  if (bond === 'stack') { units = [S]; off = 0; }
  else if (bond === 'english') { units = odd ? [hd] : [S]; off = odd ? -(hd + m) / 2 : 0; }
  else if (bond === 'flemish') { units = [S, hd]; off = odd ? -((S + m) / 2 + (hd + m) / 2) : 0; }
  else { units = [S]; off = odd ? -(S + m) / 2 : 0; }
  let x = off, k = 0;
  while (x < L) {
    const u = units[k % units.length], x0 = Math.max(0, x), x1 = Math.min(L, x + u);
    if (x1 - x0 > 0.01) {
      const id = r * 1000 + k;
      const q = addpoint(0, [(x0 + x1) / 2, (y0 + y1) / 2, (rand(id, s, 1) - 0.5) * 0.004 * j]);
      setpointattrib(0, 'scale', q, [x1 - x0, y1 - y0, d]);
      setpointattrib(0, 'orient', q, quaternion(radians((rand(id, s, 2) - 0.5) * 1.6 * j), [0, 1, 0]));
      setpointattrib(0, 'tint', q, 0.78 + 0.4 * rand(id, s, 3));
    }
    x += u + m; k++;
  }
}
